#ifndef FMT_H
#define FMT_H

#include <complex>

extern std::complex<double> fmt(double s12, double s34, double s56);

extern "C" {
  extern std::complex<double> fmt_wrapper(double s12, double s34, double s56);
}

#endif

#include <fmt.hpp>

#include <cmath>
#include <complex>
#include <masses_mod.hpp>

using namespace masses_mod;

// The full BDK expression keeps terms up to 1/mt^4 (II.15) but here
// we will only use up to 1/mt^2, as done elsewhere
//      fmt=((1._dp+(2._dp*s34+s12+s56)/15._dp/mt**2)/(24._dp*mt**2))
std::complex<double> fmt(double s12, double s34, double s56) {
  // @coverage-probe
  std::complex<double> fmt_value = (1.0) / (24.0 * pow(mt, 2));
  return fmt_value;
}

extern "C" {
  std::complex<double> fmt_wrapper(double s12, double s34, double s56) {
    return fmt(s12, s34, s56);
  }
}
